"""Infix to Prefix — reverse, convert to postfix, reverse again.

Reversing swaps the bracket directions and flips associativity, so the postfix
of the reversed expression, read backwards, is the prefix form.

Time: O(n)   Space: O(n)
"""

PRECEDENCE = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}


class Solution:
    def infixToPrefix(self, s: str) -> str:
        flipped = []
        for ch in reversed(s):
            if ch == "(":
                flipped.append(")")
            elif ch == ")":
                flipped.append("(")
            else:
                flipped.append(ch)

        out, stack = [], []
        for ch in flipped:
            if ch.isalnum():
                out.append(ch)
            elif ch == "(":
                stack.append(ch)
            elif ch == ")":
                while stack and stack[-1] != "(":
                    out.append(stack.pop())
                stack.pop()
            elif ch in PRECEDENCE:
                # Associativity is mirrored: '^' becomes left-associative here.
                while (stack and stack[-1] != "("
                       and PRECEDENCE[stack[-1]] > PRECEDENCE[ch]):
                    out.append(stack.pop())
                stack.append(ch)
        while stack:
            out.append(stack.pop())
        return "".join(reversed(out))
